<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowLeft, ArrowRight, BookOpen, Check, Download, Maximize2, X } from 'lucide-vue-next'
import { localState } from '../localState'
import { downloadText } from '../curriculum'
import { methods, matchesAnswer, assetLabel, safeSource, type MethodAsset, type MethodProgress } from '../course/methods'
import CourseImage from '../components/CourseImage.vue'
const progress = localState<MethodProgress>('methods-v3', { visited_card_ids: [], completed_question_ids: [], attempt_count: {} })
const selectedRoute = ref('入门学习'), selectedId = ref(methods.default_route[0]!), atlasOpen = ref(false), showCards = ref(false)
const routes = [{ name: '入门学习', questions: methods.default_route }, ...methods.case_tabs]
const routeQuestions = computed(() => routes.find(route => route.name === selectedRoute.value)!.questions)
const question = computed(() => methods.questions.find(q => q.question_id === selectedId.value)!)
const cards = computed(() => methods.cards.filter(c => question.value.card_ids.includes(c.card_id)))
const assets = computed(() => question.value.asset_ids.map(id => methods.assets.find(a => a.asset_id === id)!))
const answer = ref<string[]>([]), pairings = ref<Record<string, string>>({}), feedback = ref<boolean | null>(null)
const attempts = computed(() => progress.value.attempt_count[selectedId.value] || 0)
const completed = computed(() => methods.default_route.filter(id => progress.value.completed_question_ids.includes(id)).length)
const unlocked = computed(() => completed.value === methods.default_route.length)
const index = computed(() => routeQuestions.value.indexOf(selectedId.value))
const zoom = ref<HTMLDialogElement>(), enlarged = ref<MethodAsset>()
const help = ref<HTMLDialogElement>(), selectedCard = ref(methods.cards[0]!)
const cardAssets = computed(() => selectedCard.value.asset_ids.map(id => methods.assets.find(asset => asset.asset_id === id)!))
const ready = computed(() => question.value.type === 'match' ? question.value.options.every(option => pairings.value[option.id]) : answer.value.length > 0)
const targets = computed(() => question.value.type === 'match' ? [...new Set(Object.values(question.value.answer_keys))].map(id => ({ id, text: methods.assets.find(a => a.asset_id === id)?.caption || id })) : [])
watch(selectedId, () => { answer.value = []; pairings.value = {}; feedback.value = null; showCards.value = false })
function selectRoute(name: string) { selectedRoute.value = name; selectedId.value = routeQuestions.value[0]!; atlasOpen.value = false }
function changed() { feedback.value = null }
function submit() {
  if (!ready.value) return
  progress.value.attempt_count[selectedId.value] = attempts.value + 1
  const correct = matchesAnswer(question.value, question.value.type === 'match' ? pairings.value : answer.value)
  feedback.value = correct
  if (correct && !progress.value.completed_question_ids.includes(selectedId.value)) progress.value.completed_question_ids.push(selectedId.value)
  if (!correct && attempts.value >= 2) { showCards.value = true; cards.value.forEach(visitCard) }
}
function visitCard(card: typeof selectedCard.value) { if (!progress.value.visited_card_ids.includes(card.card_id)) progress.value.visited_card_ids.push(card.card_id) }
function cardSources(card: typeof selectedCard.value) { return card.source_ids.map(id => methods.references.find(reference => reference.id === id)?.title || id).join('；') }
function openCard(card: typeof selectedCard.value) { selectedCard.value = card; visitCard(card); help.value?.showModal() }
function enlarge(asset: MethodAsset) { enlarged.value = asset; zoom.value?.showModal() }
function exportProgress() { downloadText('望闻问切-学习记录.md', '# 望闻问切学习记录\n\n'+methods.questions.map(q => `- ${q.module} · ${q.prompt}：${progress.value.completed_question_ids.includes(q.question_id) ? '已完成' : '未完成'}；尝试 ${progress.value.attempt_count[q.question_id] || 0} 次`).join('\n')+`\n\n已阅读知识卡：${progress.value.visited_card_ids.join('、') || '暂无'}\n`) }
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">PLANT OBSERVATION</span><h1>望闻问切</h1><p>先整体、再局部，用多种线索核验判断。</p></div><button class="button secondary" @click="exportProgress"><Download :size="16"/>导出学习记录</button></div>
  <div class="methods-progress"><span>入门学习 {{ completed }} / {{ methods.default_route.length }}</span><progress :value="completed" :max="methods.default_route.length" aria-label="入门任务完成进度"/><button class="text-link" :disabled="!unlocked" @click="atlasOpen = !atlasOpen"><BookOpen :size="16"/>{{ unlocked ? (atlasOpen ? '收起方法图鉴' : '打开方法图鉴') : '完成入门学习后解锁图鉴' }}</button></div>
  <nav class="tab-bar methods-tabs" aria-label="植物观察案例"><button v-for="route in routes" :key="route.name" :class="{ active: selectedRoute === route.name }" :aria-pressed="selectedRoute === route.name" @click="selectRoute(route.name)">{{ route.name }}</button></nav>
  <section v-if="atlasOpen && unlocked" class="method-atlas"><h2>方法图鉴</h2><p class="muted small">按需要回看术语和案例。</p><div class="atlas-links"><button v-for="card in methods.cards" :key="card.card_id" class="button secondary compact" @click="openCard(card)">{{ card.module }} · {{ card.title }}</button></div><div class="atlas-links"><button v-for="asset in methods.assets.filter(a => a.asset_id.startsWith('R-'))" :key="asset.asset_id" class="button subtle" @click="enlarge(asset)">{{ asset.caption }}<Maximize2 :size="15"/></button></div></section>
  <div class="methods-layout"><aside class="method-steps"><h2>学习任务</h2><button v-for="(id, i) in routeQuestions" :key="id" :class="{ active: selectedId === id }" :aria-current="selectedId === id ? 'step' : undefined" @click="selectedId = id"><span>{{ i + 1 }}</span><strong>{{ methods.questions.find(q => q.question_id === id)?.prompt }}</strong><Check v-if="progress.completed_question_ids.includes(id)" :size="16"/></button><div class="method-reminder">不品尝未知植物，不采摘、剥皮或损伤保护植物。</div></aside>
  <section class="method-task"><div class="section-heading"><span class="status-tag green">{{ question.module }} · {{ index + 1 }} / {{ routeQuestions.length }}</span><span v-if="progress.completed_question_ids.includes(selectedId)" class="status-tag green">已完成</span></div><h2>{{ question.prompt }}</h2><p class="method-prompt">{{ cards[0]?.observation_prompt }}</p>
    <div class="method-images" :class="{ multiple: assets.length > 1 }"><figure v-for="asset in assets" :key="asset.asset_id"><button class="method-image-button" :aria-label="`放大${asset.caption}`" @click="enlarge(asset)"><CourseImage :src="asset.path" :alt="asset.caption"/><span><Maximize2 :size="15"/>局部放大</span></button><figcaption><strong>{{ asset.caption }}</strong><span class="media-kind">{{ assetLabel(asset) }}</span></figcaption><details class="source-details"><summary>图片来源与署名</summary><p>{{ asset.creator }} · <a v-if="safeSource(asset.license_url)" :href="safeSource(asset.license_url)" target="_blank" rel="noopener noreferrer">{{ asset.license }}</a><span v-else>{{ asset.license }}</span></p><a v-if="safeSource(asset.source_url)" :href="safeSource(asset.source_url)" class="text-link small" target="_blank" rel="noopener noreferrer">查看原始来源</a><p v-if="asset.notes">{{ asset.notes }}</p></details></figure></div>
    <div v-if="question.question_id === 'Q1'" class="method-records"><details><summary>形态记录</summary><p>叶缘有齿，多对侧脉可见；当前缺少果苞等材料。</p></details><details><summary>来源记录</summary><p>杭州的网络参考照片，不是项目采集点记录。</p></details><details><summary>植物志摘要</summary><p>应综合核对叶缘、侧脉、枝条及果苞等特征。</p></details></div>
    <details class="method-cards" :open="showCards" @toggle="($event.target as HTMLDetailsElement).open && cards.forEach(visitCard)"><summary>{{ question.module === '闻' ? '查看气味线索' : '查看知识卡' }}</summary><article v-for="card in cards" :key="card.card_id"><h3>{{ card.title }}</h3><p>{{ card.body }}</p><strong v-if="card.display_note">{{ card.display_note }}</strong><p class="source-line">来源：{{ cardSources(card) }}</p></article><div class="atlas-links"><button v-for="card in methods.cards.filter(c => c.card_id.startsWith('B'))" :key="card.card_id" class="text-link small" @click="openCard(card)">{{ card.title }}</button></div></details>
    <form class="method-answer" @submit.prevent="submit"><fieldset v-if="question.type !== 'match'"><legend>{{ question.type === 'multi' ? '多选题 · 请选择所有符合的选项' : '单选题' }}</legend><label v-for="option in question.options" :key="option.id" class="method-option"><input v-if="question.type === 'single'" type="radio" name="method-answer" :checked="answer.includes(option.id)" @change="answer = [option.id]; changed()"/><input v-else v-model="answer" type="checkbox" :value="option.id" @change="changed"/><span>{{ option.text }}</span></label></fieldset><fieldset v-else><legend>配对题 · 为每项选择对应图片或分类</legend><label v-for="option in question.options" :key="option.id" class="method-pair"><span>{{ option.text }}</span><select v-model="pairings[option.id]" :aria-label="`配对${option.text}`" @change="changed"><option value="" disabled>请选择</option><option v-for="target in targets" :key="target.id" :value="target.id">{{ target.text }}</option></select></label></fieldset><div class="form-actions"><button type="submit" class="button primary" :disabled="!ready">检查答案</button><span class="muted small">已尝试 {{ attempts }} 次</span></div></form>
    <div v-if="feedback !== null" class="method-result" :class="{ correct: feedback }" role="status"><h3>{{ feedback ? '回答正确' : '再观察一下' }}</h3><p>{{ feedback ? question.feedback_correct : attempts < 2 ? question.hint_1 : question.hint_2 }}</p><p v-if="!feedback && attempts >= 2">{{ question.feedback_wrong }}</p></div>
    <div class="method-pagination"><button class="button secondary" :disabled="index === 0" @click="selectedId = routeQuestions[index - 1]!"><ArrowLeft :size="16"/>上一题</button><button v-if="index < routeQuestions.length - 1" class="button primary" :disabled="!progress.completed_question_ids.includes(selectedId)" @click="selectedId = routeQuestions[index + 1]!">下一题<ArrowRight :size="16"/></button><button v-else-if="unlocked" class="button primary" @click="atlasOpen = true">回看方法图鉴<BookOpen :size="16"/></button></div>
  </section></div>
  <section v-if="unlocked" class="learning-entry"><div><h2>带着方法，研究森林</h2><p>你已练习寻找形态线索、使用辅助信息和核验证据。</p></div><RouterLink to="/explore?view=terrain" class="button primary">进入样带考察<ArrowRight :size="16"/></RouterLink><RouterLink to="/inquiry" class="button secondary">进入专题研究<ArrowRight :size="16"/></RouterLink></section>
  <dialog ref="zoom" class="standard-dialog method-image-dialog" aria-label="图片放大" @click="($event.target === zoom) && zoom?.close()"><div class="dialog-toolbar"><h2>{{ enlarged?.caption }}</h2><button class="icon-button" aria-label="关闭图片放大" @click="zoom?.close()"><X :size="20"/></button></div><template v-if="enlarged"><CourseImage :src="enlarged.path" :alt="enlarged.caption"/><p class="media-kind">{{ assetLabel(enlarged) }}</p><p class="source-line">{{ enlarged.creator }} · {{ enlarged.license }}</p><p>{{ enlarged.notes }}</p></template></dialog>
  <dialog ref="help" class="standard-dialog" aria-labelledby="method-card-title" @click="($event.target === help) && help?.close()"><div class="dialog-toolbar"><h2 id="method-card-title">{{ selectedCard.title }}</h2><button class="icon-button" aria-label="关闭知识卡" @click="help?.close()"><X :size="20"/></button></div><p>{{ selectedCard.body }}</p><p v-if="selectedCard.display_note">{{ selectedCard.display_note }}</p><p class="source-line">来源：{{ cardSources(selectedCard) }}</p><div class="method-images"><figure v-for="asset in cardAssets" :key="asset.asset_id"><button class="method-image-button" :aria-label="`放大${asset.caption}`" @click="enlarge(asset)"><CourseImage :src="asset.path" :alt="asset.caption"/><span><Maximize2 :size="15"/>局部放大</span></button><figcaption><strong>{{ asset.caption }}</strong><span class="media-kind">{{ assetLabel(asset) }}</span><span class="source-line">{{ asset.creator }} · {{ asset.license }}</span><a v-if="safeSource(asset.source_url)" :href="safeSource(asset.source_url)" target="_blank" rel="noopener noreferrer">图片来源</a></figcaption></figure></div></dialog>
</template>
